class Solution:
    def numIncreasingQuadruplets(self, nums: List[int]) -> int:
        n = len(nums)
        lessBefore = [0] * n
        ans = 0
        for j in range(n - 1, -1, -1):
            v = nums[j]
            great = 0
            for k in range(n - 1, j, -1):
                if nums[k] < v:
                    ans += lessBefore[k] * great
                elif nums[k] > v:
                    great += 1
            for k in range(n):
                if nums[k] > v:
                    lessBefore[k] += 1
        return ans

