class Solution {
public:
    long long numIncreasingQuadruplets(vector<int>& nums) {
        int n = nums.size();
        vector<long long> lessBefore(n, 0);
        long long ans = 0;
        for (int j = n - 1; j >= 0; --j) {
            int v = nums[j];
            long long great = 0;
            for (int k = n - 1; k > j; --k) {
                if (nums[k] < v) ans += lessBefore[k] * great;
                else if (nums[k] > v) ++great;
            }
            for (int k = 0; k < n; ++k)
                if (nums[k] > v) ++lessBefore[k];
        }
        return ans;
    }
};

