class Solution:
    def numIncreasingQuadruplets(self, nums: List[int]) -> int:
        n = len(nums)
        lt = [[0] * n for _ in range(n)]
        for j in range(1, n):
            for k in range(n):
                lt[j][k] = lt[j - 1][k] + (1 if nums[j - 1] < nums[k] else 0)
        gt = [[0] * n for _ in range(n)]
        for j in range(n):
            for k in range(n - 2, j - 1, -1):
                gt[j][k] = gt[j][k + 1] + (1 if nums[k + 1] > nums[j] else 0)
        ans = 0
        for j in range(n):
            for k in range(j + 1, n):
                if nums[k] < nums[j]:
                    ans += lt[j][k] * gt[j][k]
        return ans

